//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is eligible for another attempt.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Values below 1 are
    /// treated as one initial call.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a zero-based retry index without overflowing.
    pub(crate) fn delay_for_retry(&self, retry_index: u32) -> u64 {
        if self.max_delay_ms == 0 {
            return 0;
        }
        if self.base_delay_ms == 0 {
            return 0;
        }
        if retry_index > 0 && self.base_delay_ms >= self.max_delay_ms / 2 {
            return self.max_delay_ms;
        }
        if self.base_delay_ms >= self.max_delay_ms {
            return self.max_delay_ms;
        }

        self.base_delay_ms
            .checked_shl(retry_index)
            .unwrap_or(u64::MAX)
            .min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delays_are_bounded_and_overflow_safe() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: 100,
            max_delay_ms: 250,
        };

        assert_eq!(config.delay_for_retry(0), 100);
        assert_eq!(config.delay_for_retry(1), 200);
        assert_eq!(config.delay_for_retry(2), 250);
        assert_eq!(config.delay_for_retry(u32::MAX), 250);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 1;

    loop {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= max_attempts => {
                return Err(error);
            }
            Err(_) => {
                sleeper.sleep_ms(config.delay_for_retry(attempt - 1));
                attempt += 1;
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn retries_transient_errors_with_exponential_delays() {
        let config = RetryConfig {
            max_attempts: 4,
            base_delay_ms: 10,
            max_delay_ms: 25,
        };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            if calls < 4 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 4);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let config = RetryConfig {
            max_attempts: 3,
            base_delay_ms: 10,
            max_delay_ms: 100,
        };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let config = RetryConfig {
            max_attempts: 2,
            base_delay_ms: 10,
            max_delay_ms: 100,
        };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("temporary".into()))
        });

        assert!(matches!(result, Err(RetryError::Transient(_))));
        assert_eq!(calls, 2);
        assert_eq!(sleeper.sleeps, vec![10]);
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn transient_failure_then_success_uses_configured_retry_schedule() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 5,
        max_delay_ms: 8,
    };
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        match attempts {
            1 | 2 => Err(RetryError::Transient("service unavailable".into())),
            _ => Ok(()),
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(attempts, 3);
    assert_eq!(sleeper.sleeps, vec![5, 8]);
}

#[test]
fn permanent_failure_is_returned_on_the_first_attempt() {
    let config = RetryConfig {
        max_attempts: 10,
        base_delay_ms: 5,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        Err(RetryError::Permanent("bad request".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("bad request".into())));
    assert_eq!(attempts, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn permanent_failure_after_transient_failure_stops_immediately() {
    let config = RetryConfig {
        max_attempts: 10,
        base_delay_ms: 5,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        if attempts == 1 {
            Err(RetryError::Transient("temporary".into()))
        } else {
            Err(RetryError::Permanent("bad request".into()))
        }
    });

    assert_eq!(result, Err(RetryError::Permanent("bad request".into())));
    assert_eq!(attempts, 2);
    assert_eq!(sleeper.sleeps, vec![5]);
}

#[test]
fn zero_attempt_budget_still_makes_one_initial_call() {
    let config = RetryConfig {
        max_attempts: 0,
        base_delay_ms: 5,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        Err(RetryError::Transient("temporary".into()))
    });

    assert!(matches!(result, Err(RetryError::Transient(_))));
    assert_eq!(attempts, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn very_large_retry_index_is_capped_without_overflow() {
    let config = RetryConfig {
        max_attempts: u32::MAX,
        base_delay_ms: u64::MAX / 2,
        max_delay_ms: u64::MAX,
    };
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        if attempts == 3 {
            Ok(())
        } else {
            Err(RetryError::Transient("temporary".into()))
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(sleeper.sleeps, vec![u64::MAX / 2, u64::MAX]);
}

#[test]
fn retries_beyond_shift_width_remain_capped() {
    let config = RetryConfig {
        max_attempts: 66,
        base_delay_ms: 1,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        if attempts == 66 {
            Ok(())
        } else {
            Err(RetryError::Transient("temporary".into()))
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(attempts, 66);
    assert_eq!(sleeper.sleeps.len(), 65);
    assert!(sleeper.sleeps.iter().skip(7).all(|&delay| delay == 100));
}
